export const CONTENT_CSS = "/* WDIMTM content UI \u2014 \"Classical\" system: paper ground, ink text, gold as\n   stroke (never fill), hairline rules, small radii. Scoped by id/class\n   prefixes to limit host-page bleed. */\n\n#wdimtm-root {\n  all: initial;\n  position: fixed !important;\n  inset: 0 !important;\n  pointer-events: none !important;\n  z-index: 2147483646 !important;\n  color-scheme: dark !important;\n\n  /* Serif stacks \u2014 web fonts are never injected into the host page, so these\n     degrade to whatever classical faces the OS already has. */\n  --wdimtm-font-body: \"Lora\", Georgia, Cambria, \"Songti SC\", \"Times New Roman\", serif;\n  --wdimtm-font-heading: \"Cormorant Garamond\", \"Iowan Old Style\", \"Palatino Linotype\",\n    Palatino, \"Songti SC\", Georgia, serif;\n\n  font-family: var(--wdimtm-font-body) !important;\n\n  /* Dark tokens (ink ground) \u2014 default until applyTheme() runs */\n  --wdimtm-bg: #191817;\n  --wdimtm-fg: #f0eeea;\n  --wdimtm-muted: color-mix(in srgb, #f0eeea 62%, transparent);\n  --wdimtm-panel: #211f1e;\n  --wdimtm-border: color-mix(in srgb, #f0eeea 20%, transparent);\n  --wdimtm-header-bg: #211f1e;\n  --wdimtm-header-fg: #f7f4ef;\n  --wdimtm-body-fg: color-mix(in srgb, #f0eeea 88%, transparent);\n  --wdimtm-strong: #f7f4ef;\n  --wdimtm-subtle: color-mix(in srgb, #f0eeea 68%, transparent);\n  --wdimtm-accent: #e1ad66;\n  --wdimtm-accent-deep: #facb8d;\n  --wdimtm-code-bg: color-mix(in srgb, #f0eeea 8%, transparent);\n  --wdimtm-code-fg: #f0eeea;\n  --wdimtm-ghost-bg: transparent;\n  --wdimtm-ghost-fg: color-mix(in srgb, #f0eeea 85%, transparent);\n  --wdimtm-ghost-hover: color-mix(in srgb, #f0eeea 9%, transparent);\n  --wdimtm-chip-bg: color-mix(in srgb, #f0eeea 7%, transparent);\n  --wdimtm-chip-border: transparent;\n  --wdimtm-chip-fg: color-mix(in srgb, #f0eeea 82%, transparent);\n  --wdimtm-meta: color-mix(in srgb, #f0eeea 48%, transparent);\n  --wdimtm-link: #facb8d;\n  --wdimtm-accent-soft: #facb8d;\n  --wdimtm-label: #e1ad66;\n  --wdimtm-bubble-bg: #191817;\n  --wdimtm-bubble-border: #e1ad66;\n  --wdimtm-bubble-fg: #facb8d;\n  --wdimtm-bubble-label: color-mix(in srgb, #f0eeea 62%, transparent);\n  --wdimtm-hover: color-mix(in srgb, #f0eeea 8%, transparent);\n  --wdimtm-surface: color-mix(in srgb, #f0eeea 5%, transparent);\n  --wdimtm-surface-2: color-mix(in srgb, #f0eeea 4%, transparent);\n  --wdimtm-lens-bg: transparent;\n  --wdimtm-spinner-track: color-mix(in srgb, #f0eeea 18%, transparent);\n  --wdimtm-input-bg: transparent;\n  --wdimtm-assistant-bg: transparent;\n  --wdimtm-divider: color-mix(in srgb, #f0eeea 16%, transparent);\n  --wdimtm-selection-bg: color-mix(in srgb, #e1ad66 12%, transparent);\n  --wdimtm-error-fg: #f0b8b0;\n  --wdimtm-error-border: color-mix(in srgb, #f0b8b0 40%, transparent);\n  --wdimtm-ok-fg: #b8d3a8;\n  --wdimtm-radius: 4px;\n  --wdimtm-radius-sm: 2px;\n  --wdimtm-shadow: 0 12px 32px rgba(0, 0, 0, 0.5);\n  --wdimtm-bubble-shadow: 0 3px 10px rgba(0, 0, 0, 0.4);\n  --wdimtm-chat-shadow: 0 16px 44px rgba(0, 0, 0, 0.5);\n}\n\n#wdimtm-root[data-theme=\"light\"] {\n  color-scheme: light !important;\n\n  /* Light tokens (paper ground) */\n  --wdimtm-bg: #f3f2f2;\n  --wdimtm-fg: #201f1d;\n  --wdimtm-muted: color-mix(in srgb, #201f1d 62%, transparent);\n  --wdimtm-panel: #eae9e9;\n  --wdimtm-border: color-mix(in srgb, #201f1d 16%, transparent);\n  --wdimtm-header-bg: transparent;\n  --wdimtm-header-fg: #201f1d;\n  --wdimtm-body-fg: #201f1d;\n  --wdimtm-strong: #201f1d;\n  --wdimtm-subtle: color-mix(in srgb, #201f1d 70%, transparent);\n  --wdimtm-accent: #b68235;\n  --wdimtm-accent-deep: #7d5411;\n  --wdimtm-code-bg: color-mix(in srgb, #201f1d 5%, transparent);\n  --wdimtm-code-fg: #201f1d;\n  --wdimtm-ghost-bg: transparent;\n  --wdimtm-ghost-fg: #201f1d;\n  --wdimtm-ghost-hover: color-mix(in srgb, #201f1d 7%, transparent);\n  --wdimtm-chip-bg: #f8f4f4;\n  --wdimtm-chip-border: transparent;\n  --wdimtm-chip-fg: #444141;\n  --wdimtm-meta: color-mix(in srgb, #201f1d 48%, transparent);\n  --wdimtm-link: #7d5411;\n  --wdimtm-accent-soft: #7d5411;\n  --wdimtm-label: #b68235;\n  --wdimtm-bubble-bg: #f3f2f2;\n  --wdimtm-bubble-border: #b68235;\n  --wdimtm-bubble-fg: #7d5411;\n  --wdimtm-bubble-label: color-mix(in srgb, #201f1d 62%, transparent);\n  --wdimtm-hover: color-mix(in srgb, #201f1d 6%, transparent);\n  --wdimtm-surface: color-mix(in srgb, #201f1d 4%, transparent);\n  --wdimtm-surface-2: color-mix(in srgb, #201f1d 3%, transparent);\n  --wdimtm-lens-bg: transparent;\n  --wdimtm-spinner-track: color-mix(in srgb, #201f1d 14%, transparent);\n  --wdimtm-input-bg: transparent;\n  --wdimtm-assistant-bg: transparent;\n  --wdimtm-divider: color-mix(in srgb, #201f1d 12%, transparent);\n  --wdimtm-selection-bg: color-mix(in srgb, #b68235 10%, transparent);\n  --wdimtm-error-fg: #8a2f2f;\n  --wdimtm-error-border: color-mix(in srgb, #8a2f2f 35%, transparent);\n  --wdimtm-ok-fg: #4a6b34;\n  --wdimtm-shadow: 0 12px 32px color-mix(in srgb, #2d2b2b 22%, transparent);\n  --wdimtm-bubble-shadow: 0 3px 10px color-mix(in srgb, #2d2b2b 16%, transparent);\n  --wdimtm-chat-shadow: 0 16px 44px color-mix(in srgb, #2d2b2b 24%, transparent);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  #wdimtm-root * {\n    animation: none !important;\n    transition: none !important;\n  }\n}\n\n#wdimtm-root *,\n#wdimtm-root *::before,\n#wdimtm-root *::after {\n  box-sizing: border-box !important;\n  font-family: inherit !important;\n}\n\n#wdimtm-root ::selection {\n  background: color-mix(in srgb, var(--wdimtm-accent) 30%, transparent) !important;\n}\n\n/* \u2500\u2500 Bubble \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.wdimtm-bubble-wrap {\n  position: fixed !important;\n  display: inline-flex !important;\n  align-items: center !important;\n  gap: 6px !important;\n  padding: 3px 5px !important;\n  border-radius: 999px !important;\n  background: var(--wdimtm-bubble-bg) !important;\n  border: 1px solid var(--wdimtm-bubble-border) !important;\n  box-shadow: var(--wdimtm-bubble-shadow) !important;\n  user-select: none !important;\n  -webkit-user-select: none !important;\n}\n\n.wdimtm-bubble-wrap[hidden] {\n  display: none !important;\n}\n\n.wdimtm-bubble {\n  display: inline-flex !important;\n  align-items: center !important;\n  gap: 7px !important;\n  height: 26px !important;\n  padding: 0 8px 0 5px !important;\n  border: none !important;\n  border-radius: 999px !important;\n  background: transparent !important;\n  color: var(--wdimtm-bubble-fg) !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 13px !important;\n  font-weight: 600 !important;\n  letter-spacing: 0.01em !important;\n  line-height: 1 !important;\n  cursor: pointer !important;\n}\n\n.wdimtm-bubble:hover {\n  background: color-mix(in srgb, var(--wdimtm-accent) 12%, transparent) !important;\n}\n\n.wdimtm-lens-field {\n  position: relative !important;\n  display: inline-flex !important;\n  align-items: center !important;\n  max-width: 148px !important;\n  height: 24px !important;\n  border-radius: 0 !important;\n  background: var(--wdimtm-lens-bg) !important;\n  border: none !important;\n  border-left: 1px solid var(--wdimtm-divider) !important;\n  padding: 0 20px 0 9px !important;\n}\n\n.wdimtm-lens-caret {\n  position: absolute !important;\n  right: 5px !important;\n  top: 50% !important;\n  transform: translateY(-50%) !important;\n  font-size: 9px !important;\n  color: var(--wdimtm-muted) !important;\n  pointer-events: none !important;\n  line-height: 1 !important;\n}\n\n.wdimtm-lens-select {\n  all: unset !important;\n  box-sizing: border-box !important;\n  appearance: none !important;\n  -webkit-appearance: none !important;\n  width: 100% !important;\n  max-width: 120px !important;\n  height: 24px !important;\n  padding: 0 !important;\n  margin: 0 !important;\n  border: none !important;\n  background: transparent !important;\n  color: var(--wdimtm-bubble-label) !important;\n  font-family: var(--wdimtm-font-body) !important;\n  font-size: 12px !important;\n  font-weight: 400 !important;\n  line-height: 24px !important;\n  cursor: pointer !important;\n  text-overflow: ellipsis !important;\n  white-space: nowrap !important;\n  overflow: hidden !important;\n}\n\n.wdimtm-lens-select option {\n  color: #201f1d !important;\n  background: #f3f2f2 !important;\n  font-size: 13px !important;\n  font-weight: 400 !important;\n}\n\n.wdimtm-bubble-mark {\n  display: inline-flex !important;\n  align-items: center !important;\n  justify-content: center !important;\n  width: 18px !important;\n  height: 18px !important;\n  border-radius: 999px !important;\n  border: 1px solid var(--wdimtm-accent) !important;\n  background: transparent !important;\n  color: var(--wdimtm-accent) !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 11px !important;\n  font-weight: 600 !important;\n  flex-shrink: 0 !important;\n}\n\n.wdimtm-bubble-label {\n  color: var(--wdimtm-bubble-label) !important;\n  font-size: 11px !important;\n  font-weight: 400 !important;\n}\n\n.wdimtm-bubble-chat {\n  all: unset !important;\n  display: inline-flex !important;\n  align-items: center !important;\n  justify-content: center !important;\n  width: 24px !important;\n  height: 24px !important;\n  border-radius: 999px !important;\n  cursor: pointer !important;\n  font-size: 12px !important;\n  line-height: 1 !important;\n  color: var(--wdimtm-bubble-fg) !important;\n}\n\n.wdimtm-bubble-chat:hover {\n  background: color-mix(in srgb, var(--wdimtm-accent) 12%, transparent) !important;\n}\n\n.wdimtm-chat-header-actions {\n  display: flex !important;\n  align-items: center !important;\n  gap: 4px !important;\n  flex-shrink: 0 !important;\n}\n\n/* Window-chrome minimize (\u2500) sitting next to close (\u00d7) */\n.wdimtm-chat-min-btn {\n  font-size: 13px !important;\n  line-height: 1 !important;\n  padding-bottom: 2px !important;\n}\n\n.wdimtm-btn-tiny {\n  height: 24px !important;\n  padding: 0 9px !important;\n  font-size: 11.5px !important;\n}\n\n.wdimtm-chat-history {\n  padding: 9px 15px !important;\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n  display: flex !important;\n  flex-direction: column !important;\n  gap: 4px !important;\n  max-height: 110px !important;\n  overflow: auto !important;\n}\n\n.wdimtm-chat-history-label {\n  font-size: 9.5px !important;\n  font-weight: 400 !important;\n  color: var(--wdimtm-accent) !important;\n  text-transform: uppercase !important;\n  letter-spacing: 0.14em !important;\n}\n\n.wdimtm-chat-history-item {\n  all: unset !important;\n  display: flex !important;\n  align-items: baseline !important;\n  gap: 8px !important;\n  cursor: pointer !important;\n  padding: 6px 0 !important;\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n  font-size: 12px !important;\n  color: var(--wdimtm-fg) !important;\n}\n\n.wdimtm-chat-history-item:hover {\n  color: var(--wdimtm-accent-deep) !important;\n}\n\n.wdimtm-chat-history-item .wdimtm-chat-history-sel {\n  flex: 1 1 auto !important;\n  min-width: 0 !important;\n  overflow: hidden !important;\n  text-overflow: ellipsis !important;\n  white-space: nowrap !important;\n}\n\n/* Turn count \u2014 marks the entries that restore a real conversation. */\n.wdimtm-chat-history-count {\n  flex: 0 0 auto !important;\n  font-size: 9.5px !important;\n  letter-spacing: 0.08em !important;\n  color: var(--wdimtm-accent) !important;\n  border: 1px solid var(--wdimtm-divider) !important;\n  border-radius: 999px !important;\n  padding: 1px 6px !important;\n}\n\n.wdimtm-chat-history-item.is-active {\n  color: var(--wdimtm-accent-deep) !important;\n  font-weight: 600 !important;\n  cursor: default !important;\n}\n\n/* Past one-shot explanations, not conversations \u2014 visually recessive. */\n.wdimtm-chat-history-item.is-explain .wdimtm-chat-history-sel {\n  opacity: 0.66 !important;\n}\n\n.wdimtm-chat-suggestions {\n  display: flex !important;\n  flex-wrap: wrap !important;\n  gap: 6px !important;\n  padding: 9px 15px !important;\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n}\n\n/* \u2500\u2500 Shared surface (compact explain + expanded chat) \u2500\u2500\u2500\u2500\u2500 */\n\n/* One sheet of paper in two sizes: the explain card and the page chat carry\n   the same border, ground and elevation. */\n.wdimtm-surface {\n  border-radius: var(--wdimtm-radius) !important;\n  border: 1px solid var(--wdimtm-border) !important;\n  background: var(--wdimtm-bg) !important;\n  color: var(--wdimtm-fg) !important;\n  box-shadow: var(--wdimtm-shadow) !important;\n  overflow: hidden !important;\n  pointer-events: auto !important;\n}\n\n.wdimtm-surface-header {\n  display: flex !important;\n  align-items: center !important;\n  justify-content: space-between !important;\n  gap: 8px !important;\n  padding: 10px 14px !important;\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n  background: var(--wdimtm-header-bg) !important;\n  flex-shrink: 0 !important;\n}\n\n.wdimtm-surface-title {\n  display: flex !important;\n  align-items: center !important;\n  gap: 8px !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 13.5px !important;\n  font-weight: 600 !important;\n  color: var(--wdimtm-header-fg) !important;\n  min-width: 0 !important;\n}\n\n/* The quoted selection, shared by both modes. */\n.wdimtm-surface-selection,\n.wdimtm-chat-selection {\n  padding: 11px 15px !important;\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n  background: var(--wdimtm-selection-bg) !important;\n  flex-shrink: 0 !important;\n}\n\n.wdimtm-surface-selection-label,\n.wdimtm-chat-selection-label {\n  font-size: 9.5px !important;\n  font-weight: 400 !important;\n  color: var(--wdimtm-label) !important;\n  text-transform: uppercase !important;\n  letter-spacing: 0.14em !important;\n  margin-bottom: 5px !important;\n}\n\n.wdimtm-surface-selection-body,\n.wdimtm-chat-selection-body {\n  font-size: 12px !important;\n  line-height: 1.55 !important;\n  color: var(--wdimtm-muted) !important;\n  max-height: 4.5em !important;\n  overflow: hidden !important;\n}\n\n.wdimtm-surface-selection-body {\n  max-height: 3.2em !important;\n}\n\n/* \u2500\u2500 Popover (compact explain mode) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.wdimtm-popover {\n  position: fixed !important;\n  max-width: min(380px, calc(100vw - 16px)) !important;\n  max-height: min(440px, calc(100vh - 16px)) !important;\n  display: flex !important;\n  flex-direction: column !important;\n  animation: wdimtm-in 140ms ease-out !important;\n}\n\n.wdimtm-popover[hidden] {\n  display: none !important;\n}\n\n@keyframes wdimtm-in {\n  from {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n.wdimtm-popover-header {\n  display: flex !important;\n  align-items: center !important;\n  justify-content: space-between !important;\n  gap: 8px !important;\n  padding: 10px 14px !important;\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n  background: var(--wdimtm-header-bg) !important;\n}\n\n.wdimtm-popover-title {\n  display: flex !important;\n  align-items: center !important;\n  gap: 8px !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 13.5px !important;\n  font-weight: 600 !important;\n  color: var(--wdimtm-header-fg) !important;\n  min-width: 0 !important;\n}\n\n.wdimtm-mark {\n  display: inline-flex !important;\n  align-items: center !important;\n  justify-content: center !important;\n  width: 17px !important;\n  height: 17px !important;\n  border-radius: 999px !important;\n  border: 1px solid var(--wdimtm-accent) !important;\n  background: transparent !important;\n  color: var(--wdimtm-accent) !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 10px !important;\n  font-weight: 600 !important;\n  flex-shrink: 0 !important;\n}\n\n.wdimtm-icon-btn {\n  all: unset !important;\n  display: inline-flex !important;\n  align-items: center !important;\n  justify-content: center !important;\n  width: 26px !important;\n  height: 26px !important;\n  border-radius: var(--wdimtm-radius-sm) !important;\n  color: var(--wdimtm-muted) !important;\n  font-size: 17px !important;\n  line-height: 1 !important;\n  cursor: pointer !important;\n}\n\n.wdimtm-icon-btn:hover {\n  background: var(--wdimtm-hover) !important;\n  color: var(--wdimtm-fg) !important;\n}\n\n.wdimtm-icon-btn:focus-visible,\n.wdimtm-btn:focus-visible,\n.wdimtm-chip:focus-visible,\n.wdimtm-bubble:focus-visible,\n.wdimtm-lens-select:focus-visible {\n  outline: 2px solid var(--wdimtm-accent) !important;\n  outline-offset: 2px !important;\n}\n\n.wdimtm-toolbar {\n  margin-top: 12px !important;\n}\n\n/* \u2500\u2500 Page chat (expanded mode of the same floating surface) \u2500 */\n\n.wdimtm-chat {\n  position: fixed !important;\n  top: auto !important;\n  left: auto !important;\n  right: 16px !important;\n  bottom: 16px !important;\n  width: min(400px, calc(100vw - 24px)) !important;\n  height: min(780px, calc(100vh - 24px)) !important;\n  max-height: calc(100vh - 24px) !important;\n  display: flex !important;\n  flex-direction: column !important;\n  z-index: 2147483647 !important;\n  font-size: 13px !important;\n  /* border / ground / radius come from .wdimtm-surface */\n  box-shadow: var(--wdimtm-chat-shadow) !important;\n  transition: width 0.16s ease, height 0.16s ease, border-radius 0.16s ease !important;\n}\n\n.wdimtm-chat[hidden] {\n  display: none !important;\n}\n\n.wdimtm-chat-expanded {\n  display: flex !important;\n  flex-direction: column !important;\n  flex: 1 1 auto !important;\n  min-height: 0 !important;\n  min-width: 0 !important;\n  height: 100% !important;\n  width: 100% !important;\n}\n\n/* Collapsed = a floating mark, drawn like the selection bubble: outlined,\n   never a filled blob. `all: unset` must precede display:none. */\n.wdimtm-chat-collapsed-tab {\n  all: unset !important;\n  box-sizing: border-box !important;\n  display: none !important;\n  width: 100% !important;\n  height: 100% !important;\n  cursor: pointer !important;\n  flex-direction: row !important;\n  align-items: center !important;\n  justify-content: center !important;\n  gap: 0 !important;\n  padding: 0 !important;\n  background: var(--wdimtm-bg) !important;\n  color: var(--wdimtm-accent-deep) !important;\n  position: relative !important;\n}\n\n.wdimtm-chat-collapsed-tab:hover {\n  background: color-mix(in srgb, var(--wdimtm-accent) 12%, transparent) !important;\n}\n\n.wdimtm-chat-collapsed-tab .wdimtm-mark {\n  width: 26px !important;\n  height: 26px !important;\n  font-size: 15px !important;\n  border-color: var(--wdimtm-accent) !important;\n  background: transparent !important;\n  color: var(--wdimtm-accent) !important;\n}\n\n.wdimtm-chat-collapsed-label {\n  display: none !important;\n}\n\n/* Streaming indicator on the collapsed mark. */\n.wdimtm-chat-collapsed-dot {\n  position: absolute !important;\n  top: 8px !important;\n  right: 8px !important;\n  width: 7px !important;\n  height: 7px !important;\n  border-radius: 999px !important;\n  background: var(--wdimtm-accent) !important;\n  box-shadow: 0 0 0 2px var(--wdimtm-bg) !important;\n}\n\n.wdimtm-chat--collapsed {\n  width: 50px !important;\n  min-width: 50px !important;\n  height: 50px !important;\n  min-height: 50px !important;\n  max-height: 50px !important;\n  border-radius: 999px !important;\n  border: 1px solid var(--wdimtm-accent) !important;\n  box-shadow: var(--wdimtm-bubble-shadow) !important;\n}\n\n.wdimtm-chat--collapsed .wdimtm-chat-expanded {\n  display: none !important;\n}\n\n.wdimtm-chat--collapsed .wdimtm-chat-collapsed-tab {\n  display: flex !important;\n}\n\n.wdimtm-chat-header {\n  display: flex !important;\n  align-items: center !important;\n  justify-content: space-between !important;\n  gap: 8px !important;\n  padding: 10px 14px !important;\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n  background: var(--wdimtm-header-bg) !important;\n  flex-shrink: 0 !important;\n}\n\n.wdimtm-chat-title {\n  display: flex !important;\n  align-items: center !important;\n  gap: 8px !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 15px !important;\n  font-weight: 600 !important;\n  color: var(--wdimtm-header-fg) !important;\n}\n\n.wdimtm-chat-messages {\n  flex: 1 1 auto !important;\n  overflow: auto !important;\n  padding: 14px 15px !important;\n  display: flex !important;\n  flex-direction: column !important;\n  gap: 14px !important;\n  min-height: 0 !important;\n}\n\n.wdimtm-chat-empty {\n  color: var(--wdimtm-muted) !important;\n  font-size: 12.5px !important;\n  line-height: 1.6 !important;\n  padding: 8px 0 !important;\n}\n\n.wdimtm-chat-msg {\n  padding: 0 !important;\n  border-radius: 0 !important;\n  line-height: 1.65 !important;\n  max-width: 100% !important;\n}\n\n/* No left rule here. That treatment belongs to blockquotes inside an answer,\n   and sharing it made a question look like something the model was quoting.\n   A question is set as a heading instead: label, heading face, ink weight. */\n.wdimtm-chat-msg.user {\n  align-self: stretch !important;\n  padding-left: 0 !important;\n  border-left: 0 !important;\n  background: transparent !important;\n  color: var(--wdimtm-strong) !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 1.12em !important;\n  font-weight: 600 !important;\n  line-height: 1.4 !important;\n  letter-spacing: -0.01em !important;\n  text-align: left !important;\n}\n\n/* Same small-caps label the panel already uses for \"Selection\". */\n.wdimtm-chat-role {\n  display: block !important;\n  margin-bottom: 5px !important;\n  font-family: var(--wdimtm-font-body) !important;\n  font-size: 9.5px !important;\n  font-weight: 400 !important;\n  line-height: 1 !important;\n  letter-spacing: 0.14em !important;\n  text-transform: uppercase !important;\n  color: var(--wdimtm-label) !important;\n}\n\n.wdimtm-chat-msg.assistant {\n  align-self: stretch !important;\n  padding-bottom: 14px !important;\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n  background: transparent !important;\n  border-left: 0 !important;\n  color: var(--wdimtm-body-fg) !important;\n  text-align: justify !important;\n}\n\n.wdimtm-chat-msg.muted {\n  opacity: 0.7 !important;\n  font-style: italic !important;\n}\n\n.wdimtm-chat-search-meta {\n  margin-top: 10px !important;\n  padding-top: 9px !important;\n  border-top: 1px solid var(--wdimtm-divider) !important;\n  font-size: 11px !important;\n  line-height: 1.45 !important;\n  color: var(--wdimtm-meta) !important;\n  font-style: normal !important;\n  text-align: left !important;\n}\n\n.wdimtm-chat-composer {\n  display: flex !important;\n  flex-direction: column !important;\n  gap: 8px !important;\n  padding: 13px 15px !important;\n  border-top: 1px solid var(--wdimtm-divider) !important;\n  background: transparent !important;\n  flex-shrink: 0 !important;\n}\n\n.wdimtm-chat-input {\n  display: block !important;\n  width: 100% !important;\n  box-sizing: border-box !important;\n  resize: none !important;\n  border-radius: var(--wdimtm-radius) !important;\n  border: 1px solid var(--wdimtm-border) !important;\n  background: var(--wdimtm-input-bg) !important;\n  color: var(--wdimtm-fg) !important;\n  caret-color: var(--wdimtm-accent) !important;\n  padding: 8px 10px !important;\n  font: inherit !important;\n  font-size: 13px !important;\n  line-height: 1.5 !important;\n  min-height: 2.8em !important;\n}\n\n.wdimtm-chat-input:hover {\n  border-color: color-mix(in srgb, var(--wdimtm-fg) 45%, transparent) !important;\n}\n\n.wdimtm-chat-input:focus {\n  outline: none !important;\n  border-color: var(--wdimtm-accent) !important;\n}\n\n.wdimtm-chat-input:disabled {\n  opacity: 0.65 !important;\n  cursor: not-allowed !important;\n}\n\n.wdimtm-chat-composer.is-dropping {\n  background: var(--wdimtm-selection-bg) !important;\n}\n\n.wdimtm-chat-composer-actions {\n  display: flex !important;\n  align-items: center !important;\n  gap: 4px !important;\n}\n\n.wdimtm-chat-composer-spacer {\n  flex: 1 1 auto !important;\n}\n\n/* The picker is opened by the button next to it, never shown. */\n.wdimtm-chat-file {\n  display: none !important;\n}\n\n.wdimtm-chat-attach-hint {\n  font-size: 11px !important;\n  line-height: 1.4 !important;\n  color: var(--wdimtm-meta) !important;\n}\n\n.wdimtm-chat-composer-notice {\n  font-size: 11.5px !important;\n  line-height: 1.5 !important;\n  color: var(--wdimtm-error-fg) !important;\n  text-align: left !important;\n}\n\n/* \u2500\u2500 Image attachments \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.wdimtm-chat-attach-strip {\n  display: flex !important;\n  flex-wrap: wrap !important;\n  gap: 7px !important;\n}\n\n.wdimtm-chat-attach-item {\n  position: relative !important;\n  display: inline-flex !important;\n  width: 54px !important;\n  height: 54px !important;\n}\n\n.wdimtm-chat-attach-item img {\n  width: 100% !important;\n  height: 100% !important;\n  object-fit: cover !important;\n  border: 1px solid var(--wdimtm-border) !important;\n  border-radius: var(--wdimtm-radius-sm) !important;\n  background: var(--wdimtm-surface) !important;\n}\n\n.wdimtm-chat-attach-item button {\n  all: unset !important;\n  position: absolute !important;\n  top: -6px !important;\n  right: -6px !important;\n  display: inline-flex !important;\n  align-items: center !important;\n  justify-content: center !important;\n  width: 17px !important;\n  height: 17px !important;\n  border-radius: 50% !important;\n  border: 1px solid var(--wdimtm-border) !important;\n  background: var(--wdimtm-panel) !important;\n  color: var(--wdimtm-fg) !important;\n  font-size: 12px !important;\n  line-height: 1 !important;\n  cursor: pointer !important;\n}\n\n.wdimtm-chat-attach-item button:hover {\n  border-color: var(--wdimtm-accent) !important;\n  color: var(--wdimtm-accent) !important;\n}\n\n.wdimtm-chat-attachments {\n  display: flex !important;\n  flex-wrap: wrap !important;\n  gap: 7px !important;\n  margin-bottom: 9px !important;\n}\n\n.wdimtm-chat-attachment {\n  max-width: 180px !important;\n  max-height: 150px !important;\n  border: 1px solid var(--wdimtm-divider) !important;\n  border-radius: var(--wdimtm-radius-sm) !important;\n  object-fit: contain !important;\n  background: var(--wdimtm-surface) !important;\n}\n\n.wdimtm-chat-attachment-stub {\n  padding: 4px 8px !important;\n  border: 1px dashed var(--wdimtm-divider) !important;\n  border-radius: var(--wdimtm-radius-sm) !important;\n  font-size: 11px !important;\n  color: var(--wdimtm-meta) !important;\n}\n\n.wdimtm-popover-body {\n  padding: 14px !important;\n  overflow: auto !important;\n  font-size: 13px !important;\n  line-height: 1.68 !important;\n  color: var(--wdimtm-body-fg) !important;\n  background: var(--wdimtm-bg) !important;\n}\n\n.wdimtm-answer {\n  color: var(--wdimtm-body-fg) !important;\n  text-align: justify !important;\n  hyphens: auto !important;\n}\n\n.wdimtm-answer p {\n  margin: 0 0 0.7em !important;\n  color: inherit !important;\n}\n\n.wdimtm-answer p:last-child {\n  margin-bottom: 0 !important;\n}\n\n.wdimtm-answer strong {\n  color: var(--wdimtm-strong) !important;\n  font-weight: 600 !important;\n}\n\n.wdimtm-answer em {\n  color: var(--wdimtm-subtle) !important;\n  font-style: italic !important;\n}\n\n.wdimtm-answer code {\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace !important;\n  font-size: 0.88em !important;\n  background: var(--wdimtm-code-bg) !important;\n  padding: 0.1em 0.35em !important;\n  border-radius: var(--wdimtm-radius-sm) !important;\n  color: var(--wdimtm-code-fg) !important;\n}\n\n.wdimtm-loading {\n  display: flex !important;\n  align-items: center !important;\n  gap: 10px !important;\n  color: var(--wdimtm-muted) !important;\n  font-size: 12.5px !important;\n  min-height: 44px !important;\n}\n\n.wdimtm-spinner {\n  width: 13px !important;\n  height: 13px !important;\n  border: 1px solid var(--wdimtm-spinner-track) !important;\n  border-top-color: var(--wdimtm-accent) !important;\n  border-radius: 50% !important;\n  animation: wdimtm-spin 0.9s linear infinite !important;\n  flex-shrink: 0 !important;\n}\n\n@keyframes wdimtm-spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n.wdimtm-error {\n  color: var(--wdimtm-error-fg) !important;\n  background: transparent !important;\n  border: 1px solid var(--wdimtm-error-border) !important;\n  border-radius: var(--wdimtm-radius) !important;\n  padding: 10px 12px !important;\n  font-size: 12.5px !important;\n  line-height: 1.55 !important;\n  margin-bottom: 12px !important;\n}\n\n.wdimtm-actions {\n  display: flex !important;\n  gap: 8px !important;\n  flex-wrap: wrap !important;\n}\n\n.wdimtm-btn {\n  all: unset !important;\n  display: inline-flex !important;\n  align-items: center !important;\n  justify-content: center !important;\n  height: 28px !important;\n  padding: 0 13px !important;\n  border: 1px solid var(--wdimtm-accent) !important;\n  border-radius: var(--wdimtm-radius) !important;\n  background: transparent !important;\n  color: var(--wdimtm-accent-deep) !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 13px !important;\n  font-weight: 600 !important;\n  cursor: pointer !important;\n}\n\n.wdimtm-btn:hover {\n  background: color-mix(in srgb, var(--wdimtm-accent) 12%, transparent) !important;\n}\n\n.wdimtm-btn-ghost {\n  border-color: var(--wdimtm-border) !important;\n  background: var(--wdimtm-ghost-bg) !important;\n  color: var(--wdimtm-ghost-fg) !important;\n}\n\n.wdimtm-btn-ghost:hover {\n  background: var(--wdimtm-ghost-hover) !important;\n}\n\n.wdimtm-followups {\n  display: flex !important;\n  flex-wrap: wrap !important;\n  gap: 6px !important;\n  margin-top: 14px !important;\n  padding-top: 12px !important;\n  border-top: 1px solid var(--wdimtm-divider) !important;\n}\n\n.wdimtm-chip {\n  all: unset !important;\n  display: inline-flex !important;\n  align-items: center !important;\n  height: 22px !important;\n  padding: 0 10px !important;\n  border-radius: var(--wdimtm-radius-sm) !important;\n  border: 1px solid var(--wdimtm-chip-border) !important;\n  background: var(--wdimtm-chip-bg) !important;\n  color: var(--wdimtm-chip-fg) !important;\n  font-size: 11px !important;\n  letter-spacing: 0.02em !important;\n  cursor: pointer !important;\n}\n\n.wdimtm-chip:first-child {\n  background: transparent !important;\n  border-color: var(--wdimtm-accent) !important;\n  color: var(--wdimtm-accent-deep) !important;\n}\n\n.wdimtm-chip:hover:not(:disabled) {\n  background: color-mix(in srgb, var(--wdimtm-accent) 12%, transparent) !important;\n  border-color: var(--wdimtm-accent) !important;\n  color: var(--wdimtm-accent-deep) !important;\n}\n\n.wdimtm-chip:disabled {\n  cursor: not-allowed !important;\n  opacity: 0.5 !important;\n}\n\n.wdimtm-streaming-hint {\n  font-size: 10.5px !important;\n  color: var(--wdimtm-meta) !important;\n}\n\n.wdimtm-toast {\n  margin-top: 10px !important;\n  padding: 6px 0 !important;\n  border-top: 1px solid var(--wdimtm-divider) !important;\n  background: transparent !important;\n  color: var(--wdimtm-ok-fg) !important;\n  font-size: 11px !important;\n}\n\n/* Demo notice \u2014 sits above sample output so it is read before the answer.\n   Dashed like the hypothesis frame: both mark \"do not take this as fact\". */\n.wdimtm-demo-banner {\n  margin-bottom: 14px !important;\n  padding: 11px 13px !important;\n  border-radius: var(--wdimtm-radius) !important;\n  border: 1px dashed var(--wdimtm-accent) !important;\n  background: var(--wdimtm-selection-bg) !important;\n}\n\n.wdimtm-demo-banner-title {\n  font-family: var(--wdimtm-font-heading) !important;\n  font-size: 13px !important;\n  font-weight: 600 !important;\n  color: var(--wdimtm-accent-deep) !important;\n  margin-bottom: 5px !important;\n}\n\n.wdimtm-demo-banner-body {\n  font-size: 12px !important;\n  line-height: 1.6 !important;\n  color: var(--wdimtm-body-fg) !important;\n  text-align: justify !important;\n}\n\n.wdimtm-demo-banner .wdimtm-actions {\n  margin-top: 10px !important;\n}\n\n/* Memory suggestion \u2014 the dashed \"hypothesis, not a fact\" frame. */\n.wdimtm-memory-suggest {\n  margin-top: 14px !important;\n  padding: 11px 13px !important;\n  border-radius: var(--wdimtm-radius) !important;\n  border: 1px dashed color-mix(in srgb, var(--wdimtm-accent) 55%, transparent) !important;\n  background: transparent !important;\n}\n\n.wdimtm-memory-suggest-title {\n  font-size: 9.5px !important;\n  font-weight: 400 !important;\n  letter-spacing: 0.14em !important;\n  text-transform: uppercase !important;\n  color: var(--wdimtm-accent) !important;\n  margin-bottom: 6px !important;\n}\n\n.wdimtm-memory-suggest-body {\n  font-size: 12.5px !important;\n  color: var(--wdimtm-body-fg) !important;\n  line-height: 1.6 !important;\n  text-align: justify !important;\n}\n\n.wdimtm-memory-suggest-reason {\n  margin-top: 5px !important;\n  font-size: 10.5px !important;\n  color: var(--wdimtm-meta) !important;\n}\n\n.wdimtm-memory-suggest .wdimtm-actions {\n  margin-top: 10px !important;\n}\n\n.wdimtm-answer a {\n  color: var(--wdimtm-link) !important;\n  text-decoration: underline !important;\n  text-underline-offset: 3px !important;\n  word-break: break-word !important;\n}\n\n.wdimtm-answer ul,\n.wdimtm-answer ol {\n  margin: 0.4em 0 0.6em 1.25em !important;\n  padding: 0 !important;\n}\n\n.wdimtm-answer li {\n  margin: 0.25em 0 !important;\n}\n\n.wdimtm-answer .wdimtm-h {\n  margin: 0.7em 0 0.35em !important;\n  font-family: var(--wdimtm-font-heading) !important;\n  font-weight: 600 !important;\n  line-height: 1.25 !important;\n  color: var(--wdimtm-strong) !important;\n  letter-spacing: -0.01em !important;\n  text-align: left !important;\n}\n\n.wdimtm-answer h1.wdimtm-h {\n  font-size: 1.35em !important;\n}\n\n.wdimtm-answer h2.wdimtm-h {\n  font-size: 1.22em !important;\n}\n\n.wdimtm-answer h3.wdimtm-h {\n  font-size: 1.12em !important;\n}\n\n.wdimtm-answer .wdimtm-pre {\n  margin: 0.6em 0 0.7em !important;\n  padding: 10px 12px !important;\n  border-radius: var(--wdimtm-radius) !important;\n  border: 1px solid var(--wdimtm-border) !important;\n  background: var(--wdimtm-code-bg) !important;\n  overflow: auto !important;\n  max-width: 100% !important;\n  text-align: left !important;\n}\n\n.wdimtm-answer .wdimtm-code-block {\n  display: block !important;\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace !important;\n  font-size: 11.5px !important;\n  line-height: 1.5 !important;\n  white-space: pre !important;\n  color: var(--wdimtm-code-fg) !important;\n  background: transparent !important;\n  padding: 0 !important;\n  border-radius: 0 !important;\n}\n\n/* The \"for you\" rule \u2014 a single gold hairline, no fill. */\n.wdimtm-answer .wdimtm-quote {\n  margin: 0.6em 0 0.7em !important;\n  padding: 0 0 0 13px !important;\n  border-left: 1px solid var(--wdimtm-accent) !important;\n  color: var(--wdimtm-subtle) !important;\n}\n\n.wdimtm-answer .wdimtm-hr {\n  border: 0 !important;\n  border-top: 1px solid var(--wdimtm-divider) !important;\n  margin: 0.85em 0 !important;\n}\n\n.wdimtm-answer del {\n  opacity: 0.75 !important;\n}\n\n/* GFM tables \u2014 ruled, not filled. Header row carries the heading face. */\n.wdimtm-answer .wdimtm-table-wrap {\n  overflow-x: auto !important;\n  margin: 0.6em 0 0.75em !important;\n  max-width: 100% !important;\n  border: 1px solid var(--wdimtm-border) !important;\n  border-radius: var(--wdimtm-radius) !important;\n}\n\n.wdimtm-answer table.wdimtm-table {\n  border-collapse: collapse !important;\n  width: 100% !important;\n  min-width: 100% !important;\n  font-size: 12px !important;\n  line-height: 1.5 !important;\n  text-align: left !important;\n}\n\n.wdimtm-answer .wdimtm-table th,\n.wdimtm-answer .wdimtm-table td {\n  border-bottom: 1px solid var(--wdimtm-divider) !important;\n  padding: 7px 10px !important;\n  text-align: left !important;\n  vertical-align: top !important;\n  word-break: break-word !important;\n}\n\n.wdimtm-answer .wdimtm-table th + th,\n.wdimtm-answer .wdimtm-table td + td {\n  border-left: 1px solid var(--wdimtm-divider) !important;\n}\n\n.wdimtm-answer .wdimtm-table tbody tr:last-child td {\n  border-bottom: 0 !important;\n}\n\n.wdimtm-answer .wdimtm-table th {\n  background: transparent !important;\n  color: var(--wdimtm-accent) !important;\n  font-family: var(--wdimtm-font-body) !important;\n  font-size: 9.5px !important;\n  font-weight: 400 !important;\n  letter-spacing: 0.14em !important;\n  text-transform: uppercase !important;\n}\n\n.wdimtm-answer .wdimtm-table td {\n  font-variant-numeric: tabular-nums !important;\n}\n\n.wdimtm-chat-plain {\n  white-space: normal !important;\n  word-break: break-word !important;\n}\n\n.wdimtm-meta {\n  margin-top: 12px !important;\n  padding-top: 9px !important;\n  border-top: 1px solid var(--wdimtm-divider) !important;\n  font-size: 10px !important;\n  color: var(--wdimtm-meta) !important;\n  letter-spacing: 0.02em !important;\n}\n\n/* \u2500\u2500 Research job (#52) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 */\n\n.wdimtm-research-steps {\n  margin: 8px 0 0 1.1em !important;\n  padding: 0 !important;\n  font-size: 11.5px !important;\n  color: var(--wdimtm-muted) !important;\n}\n\n.wdimtm-research-steps li {\n  margin: 2px 0 !important;\n}\n\n.wdimtm-research-sources {\n  margin-top: 10px !important;\n  padding-top: 8px !important;\n  border-top: 1px solid var(--wdimtm-divider) !important;\n}\n\n.wdimtm-research-sources ol {\n  margin: 4px 0 0 1.2em !important;\n  padding: 0 !important;\n  font-size: 12px !important;\n}\n\n.wdimtm-research-sources li {\n  margin: 3px 0 !important;\n}\n\n.wdimtm-research-sources a {\n  color: var(--wdimtm-link) !important;\n  text-decoration: underline !important;\n  text-underline-offset: 2px !important;\n  word-break: break-word !important;\n}\n";
